import sys
sys.path.append('storage/episteme')
from factorized_mlp import FactorizedMLP
from component_test_residual_head import ResidualCopyHead
import flax.linen as nn

# Copied from storage/episteme/fact_mlp_rc.py with bug fix
class FactorizedMLP_with_RC(nn.Module):
    """
    Combines the two validated components: the FactorizedMLP and the ResidualCopyHead.
    """
    rank_k: int
    proj_rank: int

    @nn.compact
    def __call__(self, x, training: bool = False):
        y_factor = FactorizedMLP(
            rank_k=self.rank_k,
            proj_rank=self.proj_rank
        )(x, training=training)

        # FIX: ResidualCopyHead doesn't accept 'training' parameter
        y_copy = ResidualCopyHead()(x)

        return y_factor + y_copy

def _define_hyperparameters():
    return {
        'learning_rate': 0.001,
        'rank_k': 320,
        'proj_rank': 32
    }

def create_network(hparams):
    return FactorizedMLP_with_RC(
        rank_k=hparams['rank_k'],
        proj_rank=hparams['proj_rank']
    )
